mod solution;

fn main() {
    let cases = [
    (r#"[4,10,3,5,1]"#, r#"1,3,4,5,10"#),
    (r#"[0,-1]"#, r#"-1,0"#),
    (r#"
[0,-1]
"#, r#"-1,0"#),
    (r#"  
[4,10,3,5,1]
  "#, r#"1,3,4,5,10"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS heap-sort");
}
